// === Record-based case 5 - at the rejection macro ===
// The bot is about to send "Refund: Rejection - Automation" (Edit Fields32 is
// the only node that applies the rejection macro). If the customer has said on
// this ticket that they cancelled before the renewal - tag
// claim_cancelled_before_renewal, written by PS prod - Claim detection on the
// first message or any reply - the rejection is not sent and the ticket goes
// to manual CS instead (Tseko, 2026-10-15: divert only when about to reject,
// rejection macro only).
//
// Switches: record_case5_enabled runs the check, record_case5_enforce decides
// whether the rejection is stopped or the ticket is only tagged.
//
// Never throws: on any problem it reports "not matched" and the rejection goes
// out exactly as before.

let c5 = { matched: false, should_block: false };

try {
  const cfg = $('Get Project Config').first().json || {};
  function truthy(v) {
    return v === true || v === 1 || v === 'true' || v === '1' || v === 'yes';
  }
  const enabled = truthy(cfg.record_case5_enabled);
  const enforce = truthy(cfg.record_case5_enforce);

  const live = ($('Case 5: Get ticket').first().json || {}).ticket || {};
  const liveTags = Array.isArray(live.tags) ? live.tags : [];
  const claimed = liveTags.indexOf('claim_cancelled_before_renewal') !== -1;
  const matched = enabled && claimed;

  const ticketId = $('Set request data test4').first().json.original_ticket_content.ticket_id;

  // Payments facts for the note, from the lookup this flow already made.
  let body = {};
  try { body = ($('DEV bot/search').first().json || {}).body || {}; } catch (e) { body = {}; }

  function day(iso) {
    return iso ? String(iso).slice(0, 10) : '?';
  }
  const tx = Array.isArray(body.transactions) ? body.transactions.slice() : [];
  tx.sort(function (a, b) { return String(b.transactionDate || '').localeCompare(String(a.transactionDate || '')); });
  const latest = tx[0] || null;
  const refunds = Array.isArray(body.refundedTransactions) ? body.refundedTransactions : [];
  const latestRefunded = !!latest && refunds.some(function (r) { return r && r.id === latest.id; });

  let latestLine = 'no charge in the last 30 days';
  if (latest) {
    latestLine = day(latest.transactionDate) + ', ' + (latest.amount != null ? latest.amount : '?') +
      (latest.currency ? ' ' + latest.currency : '') + ', ' + (latest.type || 'unknown type') +
      (latestRefunded ? ', already refunded' : ', not refunded');
  }

  const lines = [
    'Note: This ticket matched record-based case 5 - the customer says they cancelled before the renewal, and the automation was about to send the refund rejection.',
    '',
    'Automation has been stopped and the rejection was NOT sent. Please handle this ticket manually.',
    '',
    'Subscription at lookup time:',
    '- Status: ' + (body.subscriptionStatus || 'unknown'),
    '- Cancellation date: ' + (body.cancellationDate ? day(body.cancellationDate) : 'none'),
    '- Latest charge: ' + latestLine,
    '- Refunds on record: ' + refunds.length,
    '- Provider: ' + (body.provider && body.provider.type ? body.provider.type : 'unknown')
  ];

  // A single-ticket PUT replaces the tag array, so the live tags are merged in.
  const tags = liveTags.slice();
  ['record_case_5', 'record_based_flag'].forEach(function (t) {
    if (tags.indexOf(t) === -1) tags.push(t);
  });

  const ticket = { tags: tags };
  if (matched && enforce) {
    // Allow automation is a dropdown backed by tags. Keep the merged tag list
    // consistent with the field value being set below.
    const yesIdx = tags.indexOf('_yes_');
    if (yesIdx !== -1) tags.splice(yesIdx, 1);
    if (tags.indexOf('_no_') === -1) tags.push('_no_');
    ticket.comment = { public: false, body: lines.join('\n') };
    const openStatusId = Number(cfg.ticket_custom_status_open_id);
    if (Number.isFinite(openStatusId) && openStatusId > 0) ticket.custom_status_id = openStatusId;
    const allowFieldId = Number(cfg.ticket_field_allow_automation);
    if (Number.isFinite(allowFieldId) && allowFieldId > 0) ticket.custom_fields = [{ id: allowFieldId, value: '_no_' }];
  }

  c5 = {
    matched: matched,
    should_block: matched && enforce,
    enabled: enabled,
    enforce: enforce,
    claimed: claimed,
    ticket_id: ticketId,
    zendesk_body: { ticket: ticket }
  };
} catch (e) {
  c5 = { matched: false, should_block: false, error: String(e && e.message || e) };
}

return [{ json: { case5: c5 }, pairedItem: { item: 0 } }];

// Approval gate (decision 2026-10-15): only send the approval macro if the
// payments action that ran in this execution succeeded.
// PS prod - Refund and cancellation request and PS prod - Refund request return
// { ok, refund_ok, cancel_ok } as their final output. When ok is false they have
// already posted an internal note, set the ticket to open, set Allow automation
// to no and alerted Slack, so nothing more is sent: returning no items ends the
// run here. A result without "ok" (older sub-workflow version) keeps today's
// behaviour.
const callers = [
  'Refund and cancellation', 'Refund and cancellation1', 'Refund and cancellation2',
  'Refund and cancellation3', 'Refund and cancellation4', 'Refund and cancellation5',
  'Refund and cancellation6', 'Refund and cancellation7', 'Refund and cancellation8',
  'Refund and cancellation9', 'Refund and cancellation10', 'Refund'
];
let failed = false;
for (const name of callers) {
  try {
    if ($(name).isExecuted) {
      const r = $(name).last().json || {};
      if (r.ok === false) failed = true;
    }
  } catch (e) {
    // node not on this path
  }
}
if (failed) return [];
return $input.all().map(function (it, i) { return { json: it.json, pairedItem: { item: i } }; });

